def add(cid, claim, tag, metric="", value="", unit="", period="", basis="consolidated", src=None, locator="",
        tier="1", conf="H", corr="", contra="", formula="", notes="", retrieved="2026-10-12"):
    s = src or ("", "", "", "")
    primary = "Y" if str(tier) in ("1", "2", "3", "4") else "N"
    ROWS.append([cid, "financials", claim, tag, metric, str(value), unit, period, basis, s[0], s[1], s[2], s[3],
                 retrieved if tag in ("FACT", "MANAGEMENT STATEMENT") or s[2] else "", locator, str(tier), primary,
                 conf, corr, contra, formula, notes])


